/**
 * Build-time constants. The build id is generated by scripts/write-build-id.js
 * during the deploy build (Railway commit SHA, else a build timestamp) and is
 * embedded in this bundle. The server reports the same id via /api/version,
 * so the Profile screen can tell when the bundle in the browser is stale.
 */
import buildInfo from './buildId.generated.json';

export const CLIENT_VERSION = '2.0.0';
export const CLIENT_BUILD_ID: string = buildInfo.buildId;
export const CLIENT_BUILD_AT: string = buildInfo.builtAt;
